{"command":"$ErrorActionPreference='Continue'
cd [redacted:home-path]\hacktoberfest\chidambaram-birdnudge
Write-Output "=== Common Myna in the Chidambaram pack? ==="
node -e "
const p=require('./data/pack.json');
const hits=p.species.filter(s=>/Acridotheres tristis/i.test(s.scientific));
hits.forEach(s=>console.log('  '+s.common+' ('+s.scientific+')  rank='+s.rank+'  observations='+s.observations));
console.log('  pack size: '+p.species.length+' species');
const mug=s=>p.species.filter(x=>new RegExp(s,'i').test(x.common||'')).map(x=>x.common);
console.log('');
console.log('  other starlings/mynas in pack:');
['starling','myna','sturnid'].forEach(q=>{const r=mug(q);if(r.length)console.log('    '+q+': '+r.join(', '));});
"
Write-Output ""
Write-Output "=== does extract.mjs understand 'group' / 'flock'? ==="
Select-String -Path scripts\extract.mjs -Pattern "group|flock|several|couple|pair" | ForEach-Object { "   " + $_.Line.Trim() }","timeout":300000}

{"command":"$ErrorActionPreference='Continue'
cd [redacted:home-path]\hacktoberfest\chidambaram-birdnudge
Write-Output "=== pack.json: is the 'rank' field a number or a taxonomic rank? ==="
node -e "
const p=require('./data/pack.json');
console.log('  first 3 entries:');
p.species.slice(0,3).forEach(s=>console.log('    rank='+JSON.stringify(s.rank)+'  common='+s.common));
console.log('  distinct rank values across all 130: ' + JSON.stringify([...new Set(p.species.map(s=>s.rank))]));
"
Write-Output ""
Write-Output "=== how project 1 matches species (scientific only?) ==="
Select-String -Path scripts\nudge.mjs -Pattern "binomial|scientific|common" | Select-Object -First 6 | ForEach-Object { "   " + $_.Line.Trim() }
Write-Output ""
Write-Output "=== README 'not built yet' section ==="
$idx = (Select-String -Path README.md -Pattern "^## Not built yet").LineNumber
(Get-Content README.md)[($idx-1)..($idx+9)] | ForEach-Object { "   $_" }","timeout":300000}

{"command":"$ErrorActionPreference='Continue'
cd [redacted:home-path]\hacktoberfest\chidambaram-birdnudge
node -e "
const p=require('./data/pack.json');
const hits=p.species.filter(s=>/Argya affinis/i.test(s.scientific));
if(hits.length){const s=hits[0];console.log('  IN PACK: '+s.common+' ('+s.scientific+')');console.log('  observations: '+s.observations+'   position in sorted pack: '+(p.species.findIndex(x=>x.scientific===s.scientific)+1));}
else console.log('  NOT IN PACK');
console.log('');
console.log('  all Argya babblers in pack:');
p.species.filter(s=>/Argya/i.test(s.scientific)).forEach(s=>console.log('    '+s.common+' ('+s.scientific+') obs='+s.observations));
"
Write-Output ""
Write-Output "=== is it in seasonal.json (for the nudge layer)? ==="
Select-String -Path data\seasonal.json -Pattern "Argya affinis" | ForEach-Object { "   " + $_.Line.Trim() }","timeout":300000}

{"command":"$ErrorActionPreference='Continue'
cd [redacted:home-path]\hacktoberfest\chidambaram-birdnudge
node scripts\fetch-pack.mjs 2>&1 | Select-Object -First 6
Write-Output ""
Write-Output "=== rank field now numeric? ==="
node -e "
const p=require('./data/pack.json');
p.species.slice(0,4).forEach(s=>console.log('  rank='+s.rank+'  taxRank='+s.taxonomicRank+'  '+s.common));
console.log('  distinct rank types: '+JSON.stringify([...new Set(p.species.map(s=>typeof s.rank))]));
console.log('  distinct rank values: '+JSON.stringify([...new Set(p.species.map(s=>s.rank))].slice(0,6))+' ...');
const b=p.species.find(s=>/Argya affinis/i.test(s.scientific));
console.log('  Yellow-billed Babbler rank = '+b.rank+'  (was broken before)');
"","timeout":300000}

